<?php
require_once '../includes/auth.php';
require_once '../includes/security.php';
require_once '../includes/admin_helpers.php';
require_once '../includes/updater/bootstrap.php';
$auth=new Auth();if(!$auth->isAdminLoggedIn()){header('Location: login.php');exit;}if(!AdminHelpers::canDelete()){http_response_code(403);die('Super Admin permission is required for application updates.');}
$csrf=Security::generateCSRFToken();$initialError='';$update=['current_version'=>APP_VERSION,'latest'=>null,'update_available'=>false,'last_checked_at'=>null];$active=null;$history=[];
try{[$updater]=licora_updater_services();$update=$updater->checkForUpdates(false);$active=$updater->active();$history=$updater->history(20);}catch(Throwable $e){$initialError=$e instanceof UpdateException?$e->getMessage():'Updater initialization failed. Review server logs.';error_log('Updates page init: '.$e->getMessage());}
function updater_e($v){return Security::escape((string)$v);}function updater_status_class($status){return $status==='success'?'success':($status==='rolled_back'?'warning':(in_array($status,['failed'],true)?'danger':''));}
?>
